def support(proof):
    required={len(proof)-1}
    for j in range(len(proof)-1,-1,-1):
        if j not in required:continue
        row=proof[j]
        if row['rule']=='block':required.update(row['inputs'])
        elif row['rule']=='generalize':required.add(row['source'])
    return required
def tile_reader(raw,c):
    value=reader(raw,c)
