    cost_rows=[('Complete grammar/streams/host replay',prep['seconds'],prep['peak_rss_bytes'] if 'peak_rss_bytes' in prep else max(s['peak_rss_bytes'] for s in prep['variants'])),('Independent full preparation audit',audits['audit.json']['seconds'],audits['audit.json']['peak_rss_bytes']),('Generic local compaction preparation',compact['seconds'],compact['peak_rss_bytes']),('Independent local compaction audit, attempt 2',audits['compaction-preparation-audit.json']['seconds'],audits['compaction-preparation-audit.json']['peak_rss_bytes']),('Full-edge reachability preparation',pruning['seconds'],pruning['peak_rss_bytes']),('Independent reachability replay',audits['reachability-audit.json']['seconds'],audits['reachability-audit.json']['peak_rss_bytes']),('16-query native representative pilot',pilot['seconds'],'native peaks in ledger'),('Independent whole pilot replay',audits['pilot-audit.json']['seconds'],'not separately recorded'),('20 fresh union admissions + 4 exact reuses',admission['seconds'],'native peaks in ledger'),('Independent complete union native replay',audits['admission-audit.json']['seconds'],'not separately recorded'),('Four search/whole-validation observations',search['seconds'],'per-observation peaks in ledger'),('Independent complete point/whole replay',audit['seconds'],'not separately recorded')]
